func gauntletLeaseFixture(t *testing.T) string {
	t.Helper()
	root := t.TempDir()
	projectRoot := filepath.Join(root, "projects", "alpha")
	sprintRoot := filepath.Join(projectRoot, "sprints", "31-web")
	if err := os.MkdirAll(sprintRoot, 0o755); err != nil {
