		t.Fatal(err)
	}
	return root
}

func gauntletMutate(t *testing.T, root string) error {
	t.Helper()
	svc := NewService(root)
	_, err := svc.FlowStage(context.Background(), "alpha", "31-web", FlowRequest{To: StageRequirements})
	return err
}

func TestGauntletEmptyLockFileWedgesMutationsPermanently(t *testing.T) {
	root := gauntletLeaseFixture(t)
	lockPath := filepath.Join(root, ".ultraplan", "locks", "sprint", "alpha--31-web.lock")
	if err := os.MkdirAll(filepath.Dir(lockPath), 0o755); err != nil {
		t.Fatal(err)
	}
	// Crash-of-owner residue: create() succeeded, Write never ran (or power loss).
	if err := os.WriteFile(lockPath, nil, 0o644); err != nil {
		t.Fatal(err)
	}
	for i := 0; i < 3; i++ {
		err := gauntletMutate(t, root)
		if !errors.Is(err, ErrVerificationConflict) {
			t.Fatalf("iteration %d: err=%v, want persistent ErrVerificationConflict", i, err)
		}
		if !strings.Contains(err.Error(), "unreadable") {
			t.Fatalf("iteration %d: err=%v, want unreadable-lock classification", i, err)
		}
	}
	if _, err := os.Stat(lockPath); err != nil {
		t.Fatalf("lock file removed by recovery path: %v", err)
	}
}

