package sprint

import (
	"context"
	"errors"
	"os"
	"strings"
	"sync"
	"testing"
	"time"
)

// Mechanical proof of the gap: SaveFlowState's evidence backfill rescues nil
// pointers but NOT stale non-nil pointers. Service.Status always saves stale
// non-nil Review/Smoke/QA copies it loaded before the concurrent writer
// committed, without holding the mutation lease.
func TestGauntletBackfillRescuesNilButNotStaleNonNilReview(t *testing.T) {
	root, sp := reviewFixture(t)
	now := time.Date(2026, 8, 20, 12, 0, 0, 0, time.UTC)
	reviewMD := "# Review Context\n\n# Final Assessment\n\npass\n"
	writeFileContent(t, sp.Path, reviewMD, "review.md")

	midRun := &ReviewStageState{ // what saveReviewState persists while rerunning
		Status: ReviewRunning, Path: ArtifactRelPath(sp, StageReview),
		Fingerprint: "fp-old", ArtifactDigest: hashBytes([]byte(reviewMD)), LastRunAt: &now,
		ActiveAttempt: &VerificationAttempt{ID: "review-1", Status: AttemptRunning, StartedAt: now, HeartbeatAt: now, OwnerPID: os.Getpid()},
	}
	completed := &ReviewStageState{ // what saveReviewState persists on completion
		Status: ReviewCompleted, Verdict: ReviewPass, Path: ArtifactRelPath(sp, StageReview),
		Fingerprint: "fp-new", ArtifactDigest: hashBytes([]byte(reviewMD)), LastRunAt: &now,
		LastAttempt: &VerificationAttempt{ID: "review-2", Status: AttemptCompleted, StartedAt: now, CompletedAt: &now},
		LastComplete: &ReviewCompletion{Verdict: ReviewPass, Artifact: ArtifactRelPath(sp, StageReview), ArtifactDigest: hashBytes([]byte(reviewMD)), InputFingerprint: "fp-new", CompletedAt: now},
	}

	base := NewFlowState(sp, completeStates(sp), now)

	// Case A: stale copy carries NON-nil Review (Status's actual shape) -> clobbered.
	stale := base
	stale.Review = midRun
	if err := SaveFlowState(root, sp, completedWith(base, completed)); err != nil {
		t.Fatal(err)
	}
	if err := SaveFlowState(root, sp, stale); err != nil { // Status's refresh write
		t.Fatal(err)
	}
	durable, err := LoadFlowState(root, sp)
	if err != nil {
		t.Fatal(err)
	}
	if durable.Review.Status != ReviewRunning || durable.Review.LastComplete != nil || durable.Review.ActiveAttempt == nil {
		t.Fatalf("expected terminal evidence to be clobbered by stale non-nil copy, got %+v", durable.Review)
	}

	// Case B: stale copy had nil Review -> backfill rescues the terminal record.
	os.Remove(filepath.Join(sp.Path, "flow-state.json"))
	if err := SaveFlowState(root, sp, completedWith(base, completed)); err != nil {
		t.Fatal(err)
	}
	nilCopy := base // Review == nil
	if err := SaveFlowState(root, sp, nilCopy); err != nil {
		t.Fatal(err)
	}
	durable, err = LoadFlowState(root, sp)
	if err != nil {
		t.Fatal(err)
	}
	if durable.Review == nil || durable.Review.Status != ReviewCompleted {
		t.Fatalf("backfill should rescue nil pointer case, got %+v", durable.Review)
	}
}

func completedWith(base FlowState, r *ReviewStageState) FlowState {
	out := base
	out.Review = r
	return out
}

// End-to-end: hammer the real Service.Status concurrently with a mutation
// writer cycling review records; after the writer's final TERMINAL save and
// quiescence of all Status calls, durable state must be terminal.
func TestGauntletRealStatusRaceLosesTerminalReviewRecord(t *testing.T) {
	root, sp := reviewFixture(t)
	big := "#" + strings.Repeat(" requirement context ", 200000) + "\n"
	writeFileContent(t, sp.Path, big, "requirements.md") // widen PrepareReview window

	now := time.Date(2026, 8, 20, 12, 0, 0, 0, time.UTC)
	digest := func() string { data, _ := os.ReadFile(filepath.Join(sp.Path, "review.md")); return hashBytes(data) }()
	base := NewFlowState(sp, completeStates(sp), now)
	running := func(i int) FlowState {
		s := base
		s.Review = &ReviewStageState{Status: ReviewRunning, Path: ArtifactRelPath(sp, StageReview), Fingerprint: "fp", ArtifactDigest: digest, LastRunAt: &now,
			ActiveAttempt: &VerificationAttempt{ID: "a", Status: AttemptRunning, StartedAt: now, HeartbeatAt: now, OwnerPID: os.Getpid()}}
		return s
	}
	terminal := func() FlowState {
		s := base
		s.Review = &ReviewStageState{Status: ReviewCompleted, Verdict: ReviewPass, Path: ArtifactRelPath(sp, StageReview), Fingerprint: "fp", ArtifactDigest: digest, LastRunAt: &now,
			LastAttempt:  &VerificationAttempt{ID: "b", Status: AttemptCompleted, StartedAt: now, CompletedAt: &now},
			LastComplete: &ReviewCompletion{Verdict: ReviewPass, Artifact: ArtifactRelPath(sp, StageReview), ArtifactDigest: digest, InputFingerprint: "fp", CompletedAt: now}}
		return s
	}

	stop := make(chan struct{})
	var wg sync.WaitGroup
	clobbered := make(chan struct{}, 1)
	wg.Add(1)
	go func() { // mutation writer owning the lease (as review would)
		defer wg.Done()
		for i := 0; i < 300; i++ {
			select {
			case <-stop:
				return
			default:
			}
			_ = SaveFlowState(root, sp, running(i))
			_ = SaveFlowState(root, sp, terminal()) // last write by owner is terminal
			select {
			case <-stop:
				return
			case <-time.After(time.Microsecond):
			}
		}
	}()
	svc := NewService(root).WithClock(func() time.Time { return now })
	done := make(chan struct{})
	wg.Add(1)
	go func() {
		defer wg.Done()
		defer close(done)
		for {
			select {
			case <-stop:
				return
			default:
			}
			if _, err := svc.Status("proj", "01"); err != nil && !errors.Is(err, ErrFlowStateMissing) {
				select {
				case <-stop:
					return
				default:
					t.Logf("status error (tolerated): %v", err)
				}
			}
		}
	}()
	// Let them contend briefly, then stop writers and wait for quiescence.
	time.Sleep(1500 * time.Millisecond)
	close(stop)
	<-done
	wg.Wait()
	// Writer goroutine may still be inside its final pair when stopped; give it
	// the same quiescence: its loop checks stop between pairs, so after wg.Wait
	// every started pair finished with terminal as the final save... unless the
	// goroutine returned early at the select AFTER running-save. Re-write the
	// terminal record one final time to remove that ambiguity, then let ONE more
	// concurrent Status run against it.
	_ = SaveFlowState(root, sp, terminal())
	var single sync.WaitGroup
	single.Add(1)
	go func() { defer single.Done(); _, _ = svc.Status("proj", "01") }()
	single.Wait()

	durable, err := LoadFlowState(root, sp)
	if err != nil {
		t.Fatal(err)
	}
	if durable.Review.Status != ReviewCompleted {
		select {
		case clobbered <- struct{}{}:
		default:
		}
		t.Fatalf("DEFECT REPRODUCED: durable review=%+v (owner's final record was terminal/completed)", durable.Review)
	}
}
EOF
